window.docContents[82].resolve({"/LindenstraussPolynomials/Theorems/#LindenstraussPolynomials___polynomial_lindenstrauss":{"contents":"Theorem thm:main (polynomial Lindenstrauss theorem, scalar-valued; 𝕜 = ℝ or ℂ).\nFor every continuous n-homogeneous polynomial P : X → 𝕜 (n ≥ 1) and every ε > 0\nthere are a continuous n-homogeneous polynomial Q with ‖Q - P‖ < ε and a point z\nof the closed unit ball of X** with |Q̃(z)| = ‖Q̃‖ = ‖Q‖. \n\n","context":"","header":"LindenstraussPolynomials.polynomial_lindenstrauss","id":"/LindenstraussPolynomials/Theorems/#LindenstraussPolynomials___polynomial_lindenstrauss"}});